// Provisional SVG illustration of each layer (viewBox 420x145).
const svg=(body)=>`<svg viewBox="0 0 420 145" aria-hidden="true"><defs><linearGradient id="bun" x2="0" y2="1"><stop stop-color="#ffca63"/><stop offset=".6" stop-color="#cc661c"/><stop offset="1" stop-color="#8d340e"/></linearGradient><linearGradient id="meat" x2="0" y2="1"><stop stop-color="#793419"/><stop offset=".5" stop-color="#482011"/><stop offset="1" stop-color="#26140e"/></linearGradient><linearGradient id="cheese" x2="0" y2="1"><stop stop-color="#ffd64b"/><stop offset="1" stop-color="#f18c05"/></linearGradient></defs>${body}</svg>`;
// Sauce dollops shared by ketchup and maionese, from the middle to near the ends; the colours
// differ, and the mayo's are smaller (squashed under the top bun).
const sauce=(fill,stroke,shine,k=1)=>svg([[40,74,20],[92,66,15],[140,76,24],[196,64,14],[244,75,22],[296,65,16],[342,76,21],[384,70,14]].map(([x,y,r])=>(r*=k,`<path d="M${x-r} ${y}Q${x-r} ${y-r*.8} ${x} ${y-r*.7}Q${x+r} ${y-r*.8} ${x+r} ${y}Q${x+r*.6} ${y+r*.9} ${x} ${y+r*.7}Q${x-r*.6} ${y+r*.9} ${x-r} ${y}Z" fill="${fill}" stroke="${stroke}" stroke-width="2"/><ellipse cx="${x-r*.3}" cy="${y-r*.3}" rx="${r*.35}" ry="${r*.18}" fill="${shine}"/>`)).join(''));
// Cebola crispy: a loose heap of fried crumbs and short curled strands, no solid body: dark
// pieces at the bottom of the heap, lighter ones on top, a few spilling past the ends; bare
// patches between the clumps.
function crispyOnion(){let s=7;const r=()=>(s=(s*16807)%2147483647)/2147483647,cols=['#6e3a16','#8a4c1c','#a8642a','#b87430','#c98a3a','#dca04a','#eab866'];let c='';for(let i=0;i<300;i++){const t=i/300,x=26+r()*368,d=Math.abs(x-210)/184,top=88-(1-d*d)*34-r()*8,y=96-(96-top)*(.25+.75*t)+r()*4,k=Math.min(6,Math.floor(t*4+r()*3.5)),f=cols[k];if(Math.sin(x*.05+1.3)+Math.sin(x*.13+.4)>1.05&&t>.3)continue;if(r()<.35){const a=r()*6.3,l=8+r()*9,q=r()*10-5;c+=`<path d="M${(x-Math.cos(a)*l).toFixed(1)} ${(y-Math.sin(a)*l*.4).toFixed(1)}q${(Math.cos(a)*l+q).toFixed(1)} ${(q-3).toFixed(1)} ${(Math.cos(a)*l*2).toFixed(1)} ${(Math.sin(a)*l*.8).toFixed(1)}" fill="none" stroke="${f}" stroke-width="${(3+r()*2.2).toFixed(1)}" stroke-linecap="round"/>`;}else{const n=5,z=4.5+r()*5.5;let p='';for(let v=0;v<n;v++){const a=v/n*6.283+r()*.6,m=z*(.55+r()*.6);p+=`${v?'L':'M'}${(x+Math.cos(a)*m).toFixed(1)} ${(y+Math.sin(a)*m*.65).toFixed(1)}`;}c+=`<path d="${p}Z" fill="${f}"/>`;}}return svg(c);}
// Cheddar (Cheddar Duplo): gooey orange melted cheddar with an uneven outline and two holes
// showing the meat; a few short drips: wide concave fillets out of it, a soft neck, a round
// glossy drop, all within the patty's height.
function cheddar(){const f=(v)=>+v.toFixed(1),drips=[[52,22],[176,18],[300,30],[362,26]].map(([x,l])=>{const t=(400-x)/380,yb=94+36*t*(1-t),y0=yb-6,rb=9.5,n=5,w=20,cy=yb+14+0.35*l-rb;return `<path d="M${f(x-w)} ${f(y0)}C${x-n-3} ${f(y0)} ${x-n} ${f(yb+2)} ${x-n} ${f(yb+7)}C${x-n} ${f(cy-rb*.6)} ${f(x-rb)} ${f(cy-rb*.5)} ${f(x-rb)} ${f(cy)}A${rb} ${rb} 0 0 0 ${f(x+rb)} ${f(cy)}C${f(x+rb)} ${f(cy-rb*.5)} ${x+n} ${f(cy-rb*.6)} ${x+n} ${f(yb+7)}C${x+n} ${f(yb+2)} ${x+n+3} ${f(y0)} ${f(x+w)} ${f(y0)}Z" fill="#f59a0c"/><ellipse cx="${f(x-3.5)}" cy="${f(cy-2)}" rx="3" ry="3.6" fill="#ffc24a"/>`}).join('');return svg(`<path d="M18 62C50 44 130 50 190 46S330 40 398 58C414 66 412 86 400 94C350 104 300 92 250 102S110 104 22 94C6 88 6 68 18 62Z" fill="#f59a0c"/>${drips}<ellipse cx="148" cy="70" rx="26" ry="7" fill="#4a2414" stroke="#ffb02e" stroke-width="3"/><ellipse cx="282" cy="74" rx="17" ry="5" fill="#4a2414" stroke="#ffb02e" stroke-width="3"/><path d="M38 56Q210 38 382 56" stroke="#ffc24a" fill="none" stroke-width="5" stroke-linecap="round"/>`);}
// Bacon (Stacker Duplo Bacon): three wavy strips across the burger, ends past both sides:
// lean red-brown, a paler fat streak along each, darker toasted rims.
function bacon(){const f=(v)=>+v.toFixed(1);return svg([[66,0],[78,2.1],[90,4.2]].map(([y0,ph],k)=>{let d='';for(let i=0;i<=40;i++){const x=6+i*10.2,y=y0+Math.sin(x*.045+ph)*7-k*2;d+=`${i?'L':'M'}${f(x)} ${f(y)}`;}return `<path d="${d}" fill="none" stroke="#4a1a0c" stroke-width="17" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="#9a3418" stroke-width="13" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="#eab48c" stroke-width="3.5" stroke-linecap="round" stroke-dasharray="46 14" transform="translate(0 -2)"/>`}).join(''));}
// Molho Stacker: a creamy pinkish-orange band spread across the burger (it covers the middle,
// where the opened Camada is tapped), wavy on top, with drips hanging at a few points.
function stackerSauce(){const drips=[[70,14],[168,10],[262,16],[350,11]].map(([x,l])=>`<path d="M${x-9} 84Q${x-8} ${92+l} ${x} ${94+l}Q${x+8} ${92+l} ${x+9} 84Z" fill="#ec8a64"/>`).join('');return svg(`<path d="M22 70Q40 56 70 62T130 58T200 60T270 56T340 60T398 68Q408 78 396 86Q350 92 300 88T200 90T100 88T26 84Q12 78 22 70Z" fill="#ec8a64" stroke="#b85a3c" stroke-width="2"/>${drips}<path d="M48 66Q120 56 200 62T372 64" fill="none" stroke="#ffc3a6" stroke-width="4" stroke-linecap="round"/>`);}
// Molho barbecue (Rodeio Duplo): a dark brown, glossy band spread across the burger (it covers
// the middle, where the opened Camada is tapped), with drips hanging over the edge.
function bbqSauce(){const drips=[[58,12],[150,9],[248,14],[352,10]].map(([x,l])=>`<path d="M${x-8} 82Q${x-7} ${90+l} ${x} ${92+l}Q${x+7} ${90+l} ${x+8} 82Z" fill="#4a1c0c"/>`).join('');return svg(`<path d="M20 70Q40 58 72 63T136 60T204 62T272 58T340 62T398 69Q408 78 396 85Q350 90 300 86T200 88T100 86T24 83Q10 78 20 70Z" fill="#4a1c0c" stroke="#2a0e05" stroke-width="2"/>${drips}<path d="M52 66Q124 58 204 63T368 65" fill="none" stroke="#a0522d" stroke-width="3.5" stroke-linecap="round"/>`);}
// Onion rings (Rodeio Duplo): two thick golden breaded rings side by side, past both ends,
// the barbecue showing through their holes (painted, so the middle still takes the tap).
function onionRings(){return svg([108,312].map((x)=>`<ellipse cx="${x}" cy="74" rx="104" ry="36" fill="#a5601f"/><ellipse cx="${x}" cy="68" rx="102" ry="33" fill="#d8902f" stroke="#f0b660" stroke-width="3"/><ellipse cx="${x}" cy="68" rx="56" ry="14" fill="#4a1c0c" stroke="#9a561c" stroke-width="4"/>`).join(''));}
// Queijo: the Whopper's slice; the Stacker Duplo Bacon's cheddar is the same slice in cheddar orange.
const cheese=(fill='url(#cheese)',rim='#ffe774')=>svg(`<path d="M14 60L210 42L406 60L400 76L362 82Q354 112 341 114Q329 112 322 86L252 90Q220 128 207 126Q194 124 176 90L104 86Q94 114 81 114Q68 112 64 84L20 78Z" fill="${fill}"/><path d="M24 62L210 48L396 62" stroke="${rim}" fill="none" stroke-width="5" stroke-linecap="round"/>`);
export function art(id){if(id==='bbqSauce')return bbqSauce();if(id==='onionRings')return onionRings();if(id==='bacon')return bacon();if(id==='stackerSauce')return stackerSauce();if(id==='cheddarSlice')return cheese('#f59a0c','#ffc24a');if(id==='crispyOnion')return crispyOnion();if(id==='cheddar')return cheddar();if(id==='ketchup')return sauce('#c8240f','#8f1708','#f0705a');if(id==='mayo')return sauce('#fbf1d6','#dcc89a','#ffffff',.6);if(id==='top'){let seeds='';for(let i=0;i<42;i++){const x=45+(i*73%325),y=47+(i*31%40);seeds+=`<ellipse cx="${x}" cy="${y}" rx="4" ry="1.7" fill="#ffeab1" transform="rotate(${i*47%100-50} ${x} ${y})"/>`;}return svg(`<path d="M20 109C24 4 383 4 400 109Q210 154 20 109" fill="url(#bun)"/><path d="M32 106Q210 145 388 106" fill="none" stroke="#eaa251" stroke-width="5"/>${seeds}`)}if(id==='bottom')return svg('<path d="M23 63Q210 32 397 63L390 107Q210 158 30 106Z" fill="url(#bun)"/><ellipse cx="210" cy="65" rx="187" ry="28" fill="#edaf56"/><path d="M35 101Q210 139 382 104" fill="none" stroke="#a74c15" stroke-width="5"/>');if(id==='meat')return svg('<path d="M15 63Q25 48 45 49Q80 35 109 48Q140 33 170 46Q200 34 230 44Q270 35 300 45Q350 37 397 61L405 88Q390 125 345 118Q300 133 270 120Q210 134 166 121Q120 133 87 118Q39 126 17 98Z" fill="url(#meat)"/><path d="M37 63L82 95M95 56L145 107M165 54L215 107M240 54L285 106M315 57L362 96" stroke="#21110b" stroke-width="8" stroke-linecap="round"/><path d="M28 66Q210 28 395 66" fill="none" stroke="#ae6336" stroke-width="5"/>');if(id==='cheese')return cheese();if(id==='lettuce'){let l='';[[92,74,'#639a1c'],[322,72,'#447b16'],[160,66,'#8eb72b'],[262,68,'#639a1c']].forEach(([cx,cy,c],k)=>{let d='';for(let i=0;i<36;i++){const a=i/36*6.283,m=1+.14*Math.sin(a*5+k*2)+.09*Math.sin(a*13+k),x=cx+Math.cos(a)*88*m,y=cy+Math.sin(a)*30*m;d+=`${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`;}l+=`<path d="${d}Z" fill="${c}" stroke="#a4c747" stroke-width="2"/><path d="M${cx-60} ${cy+6}Q${cx} ${cy-10} ${cx+62} ${cy+2}" fill="none" stroke="#c6dc7a" stroke-width="3" stroke-linecap="round"/>`;});return svg(l)}if(id==='tomato')return svg([75,192,313].map(x=>`<ellipse cx="${x}" cy="75" rx="67" ry="24" fill="#c12a0f"/><ellipse cx="${x}" cy="67" rx="66" ry="23" fill="#f34820" stroke="#ff8060" stroke-width="3"/><ellipse cx="${x}" cy="66" rx="45" ry="13" fill="#d33215"/><path d="M${x-35} 66h70M${x} 56v22" stroke="#ffad61" stroke-width="3"/>`).join(''));if(id==='onion')return svg([80,198,318].map(x=>`<ellipse cx="${x}" cy="73" rx="70" ry="23" fill="#ead7a8"/><ellipse cx="${x}" cy="67" rx="65" ry="20" fill="#fff4d3"/><ellipse cx="${x}" cy="67" rx="51" ry="13" fill="#fff4d3" stroke="#cdb79a" stroke-width="3"/>`).join(''));return svg([65,150,245,330].map((x,i)=>`<ellipse cx="${x}" cy="70" rx="44" ry="18" fill="#517219"/><ellipse cx="${x}" cy="65" rx="43" ry="16" fill="#93a636" stroke="#466919" stroke-width="4"/><ellipse cx="${x}" cy="65" rx="24" ry="8" fill="#bdc866"/>`).join(''))}
